import icon_pools from '@/assets/images/icon_pools@2x.png'
import icon_positions from '@/assets/images/icon_positions@2x.png'
import pool_bg from '@/assets/images/pool_bg.png'
import useStatistics from '@/hooks/stats/useStatistics'
import usePoolsStore from '@/store/pool'
import { SelectTab } from '@cetus/design'
import { VTextLabelBox } from '@cetus/ui-kit'
import { Box, Button, HStack, Text, VStack } from '@chakra-ui/react'
import { useEffect, useMemo, useState } from 'react'
import { useLocation, useNavigate } from 'react-router-dom'
import VolChartPageBlock from '../stats/VolChartPageBlock'

function PoolsTopData() {
  const { pathname } = useLocation()
  const navigate = useNavigate()
  const { getStatistics } = useStatistics()
  const [statisticsData, seStatisticsData] = useState<any>(null)
  const fetStatisticsData = async () => {
    const result: any = await getStatistics()
    if (result) {
      console.log('🚀 ~ fetchDataStatisticsData ~ result:', result)
      seStatisticsData(result)
    }
  }
  useEffect(() => {
    fetStatisticsData()
  }, [])
  const { poolListLength } = usePoolsStore()
  const tabList = useMemo(() => {
    console.log('🚀 ~ PoolsTopData ~ poolListLength:', poolListLength)
    return [
      {
        label: 'Pools',
        value: 'pools',
        num: poolListLength == '--' ? '' : poolListLength,
        imgInfo: {
          src: icon_pools,
          w: '22px',
          h: '22px'
        }
      },
      {
        label: 'My Positions',
        value: 'positions',
        imgInfo: {
          src: icon_positions,
          w: '22px',
          h: '22px'
        }
      }
    ]
  }, [poolListLength])
  const currentTabVal = useMemo(() => {
    return pathname?.split('/')[1] || 'pools'
  }, [pathname])
  return (
    <VStack w="100%" background="bg_primary">
      <HStack
        w="100%"
        gap={{
          base: '12px',
          lg: '32px'
        }}
        flexDirection={{
          base: 'column',
          lg: 'row'
        }}
      >
        <VStack
          w={{
            base: '100%',
            lg: '420px'
          }}
          justify="space-between"
          align="flex-start"
          gap={{
            base: '12px',
            lg: '40px'
          }}
        >
          <Text fontSize="24px" fontWeight="500" color="text_caption">
            Liquidity Pools
          </Text>
          <VStack
            gap="80px"
            p="42px 40px"
            align={{
              base: 'center',
              lg: 'flex-start'
            }}
            borderRadius="16px"
            bgImage={pool_bg}
            w="100%"
            h="280px"
            backgroundSize="100% 100%"
          >
            <VTextLabelBox
              alignItems="center"
              title="Total Value Locked"
              titleFontSize="16px"
              valueFontSize="24px"
              value={statisticsData?.totalValueLocked}
            />
            <VTextLabelBox title="Cumulative Volume" titleFontSize="16px" valueFontSize="24px" value={statisticsData?.cumulativeVolume} />
          </VStack>
        </VStack>
        <Box
          h="100%"
          w={{
            base: '100%',
            lg: 'calc(100% - 420px)'
          }}
        >
          <VolChartPageBlock statisticsData={statisticsData} pageFrom="pools" />
        </Box>
      </HStack>
      <HStack
        w="100%"
        mt="32px"
        justify="space-between"
        flexDirection={{
          base: 'column-reverse',
          lg: 'row'
        }}
      >
        <SelectTab
          type="borderTab"
          wrapStyle={{
            w: {
              base: '100%',
              lg: '395px'
            },
            h: '60px'
          }}
          itemStyle={{
            w: '50%',
            fontSize: '16px'
          }}
          tabList={tabList}
          currentTab={currentTabVal == 'positions' ? 'My Positions' : 'Pools'}
          handleChangeTab={item => {
            if (item.value == 'positions') {
              navigate('/positions')
            } else {
              navigate('/pools')
            }
          }}
        />
        <HStack w={{ base: '100%', lg: 'unset' }}>
          <Button w={{ base: '50%', lg: '168px' }} fontWeight="500" variant="outline">
            Create a new pool
          </Button>
          <Button fontWeight="500" w={{ base: '50%', lg: '168px' }}>
            Add Liquidity
          </Button>
        </HStack>
      </HStack>
    </VStack>
  )
}

export default PoolsTopData
