import PoolsContent from '@/components/pools/PoolsContent'
import PoolsTopData from '@/components/pools/PoolsTopData'
import PositionsContent from '@/components/position/list/PositionsContent'
import { VStack } from '@chakra-ui/react'
import { useMemo } from 'react'
import { useLocation } from 'react-router-dom'

function Pools() {
  const { pathname } = useLocation()
  const currentTabVal = useMemo(() => {
    return pathname?.split('/')[1] || 'pools'
  }, [pathname])
  return (
    <VStack gap="20px" w="100%" background="bg_primary" pt="40px">
      <PoolsTopData />
      {currentTabVal == 'pools' && <PoolsContent />}
      {currentTabVal == 'positions' && <PositionsContent />}
    </VStack>
  )
}

export default Pools
