import icon_active from '@/assets/images/icon_active@2x.png'
import img_inactive from '@/assets/images/img_inactive@2x.png'
import { Box, Image, Text, Tooltip, VStack } from '@chakra-ui/react'

function PositionStatus({ status = 'Active' }: { status: string }) {
  const isActive = status == 'Active'
  return (
    <Box>
      <Tooltip
        label={
          <Text fontSize="12px">
            {isActive
              ? 'The price of this pool is currently within your position price range.'
              : 'The price of this pool is currently out of your position price range.'}
          </Text>
        }
        aria-label="Yield"
        placement="top"
      >
        <button>
          <VStack gap="0">
            <Image w="36px" h="20px" src={isActive ? icon_active : img_inactive} />
            <Text color={isActive ? 'primary' : 'primary_gray'}>{isActive ? 'Active' : 'Inactive'}</Text>
          </VStack>
        </button>
      </Tooltip>
    </Box>
  )
}

export default PositionStatus
