import { useGetToken } from '@cetus/hooks/src/useToken'
import { SingleCoinImage } from '@cetus/ui-kit'
import { fixRounding, formatNumber, fromDecimalsAmountFix } from '@cetus/utils'
import { Box, Center, HStack, Popover, PopoverBody, PopoverContent, PopoverTrigger, Portal, Text } from '@chakra-ui/react'
import { useEffect, useState } from 'react'

function RewardsBlock({ miningRewardList }: { miningRewardList: any[] }) {
  const { getTokenInfo } = useGetToken()
  const [activeTooltip, setActiveTooltip] = useState<string | null>(null)
  const [rewardsList, setRewardsList] = useState<any>([])

  const handleMouseEnter = (coinType: string) => {
    setActiveTooltip(coinType)
  }

  const handleMouseLeave = () => {
    setActiveTooltip(null)
  }

  useEffect(() => {
    const fetchData = async () => {
      if (miningRewardList.length > 0) {
        try {
          const list = await Promise.all(
            miningRewardList.map(async (item: any) => {
              const tokenInfo = await getTokenInfo(item?.coinType)
              return { ...item, tokenInfo }
            })
          )
          setRewardsList(list)
          console.log('🚀 ~ list:', list)
        } catch (error) {
          console.error('Error processing list:', error)
        }
      }
    }

    fetchData()
  }, [miningRewardList])

  return (
    <HStack w="100%" justify="flex-end">
      {rewardsList.map((item: any) => (
        <Box
          key={item?.coinType}
          onClick={(e: any) => e.stopPropagation()}
          onMouseEnter={() => handleMouseEnter(item?.coinType)}
          onMouseLeave={handleMouseLeave}
        >
          <Popover isOpen={activeTooltip === item?.coinType} placement="top">
            <PopoverTrigger>
              <Center>
                <SingleCoinImage imageUrl={item?.tokenInfo?.logo_url} w="24px" h="24px" />
              </Center>
            </PopoverTrigger>
            {activeTooltip === item?.coinType && (
              <Portal>
                <PopoverContent zIndex="2" minW="unset" w="unset" border="1px solid" borderColor="border" p="4px">
                  <PopoverBody borderRadius="12px">
                    <HStack gap="4px">
                      <Box>
                        <SingleCoinImage imageUrl={item?.tokenInfo?.logo_url} w="24px" h="24px" />
                      </Box>
                      <Text color="primary" display="inline-block">
                        {/* 处理精度后向上取整展示位隔符 */}
                        {formatNumber(fixRounding(fromDecimalsAmountFix(item?.emissionsEveryDay, item?.tokenInfo?.decimals), 2))}{' '}
                        {item?.tokenInfo.symbol} per day
                      </Text>
                    </HStack>
                  </PopoverBody>
                </PopoverContent>
              </Portal>
            )}
          </Popover>
        </Box>
      ))}
    </HStack>
  )
}
export default RewardsBlock
